     * @description resolves or rejects a one-shot command and forgets its subscription so the same command can be sent again
     * @param {object} client the websocket client
     * @param {string} messageHash the message hash of the command
     * @param {object} result the value to resolve with
     * @param {object} [error] when set the command is rejected with it instead
     */
    public virtual void settleRequest(WebSocketClient client, string messageHash, object result, object error = null)
    {
        if ((client.subscriptions != null && client.subscriptions.ContainsKey(messageHash)))
        {
            ((IDictionary<string,object>)client.subscriptions).Remove(messageHash);
        }
        if ((error != null))
        {
            client.reject(error, messageHash);
        } else
        {
            client.resolve(result, messageHash);
        }
    }

    public virtual void handleCreateOrder(WebSocketClient client, Dictionary<string, object> message)
    {
        //
        //     {
        //         "event": "added-order",
        //         "symbol": "BTC/USDC",
        //         "data": {
        //             "id": "f0f895d1-f9e0-494c-87b4-40e12ce344a1",
        //             "userId": "7bd4cc22-7682-4e45-85b3-29386b979d75",
        //             "side": "buy",
        //             "symbol": "BTC/USDC",
        //             "status": "open",
        //             "orderType": "limit",
        //             "createdAt": "2026-11-11T06:27:02.617Z",
        //             "updatedAt": "2026-11-11T06:27:02.617Z",
        //             "clientOrderId": "c4022a5f-cfb3-46ff-9136-2739e34dd4e6",
        //             "cancelReason": null,
        //             "timeInForce": "GTC",
        //             "feeCurrency": null,
        //             "price": 36000,
        //             "orderAmount": 0.0001,
        //             "filledAmount": 0,
        //             "cost": 0,
        //             "stopPrice": 0,
        //             "feeAmount": 0,
        //             "orderGroupId": null
        //         }
        //     }
        //
        IDictionary<string, object> data = this.safeDict(message, "data", new Dictionary<string, object>() {});
        ccxt.Order order = this.parseOrder(data);
        string? clientOrderId = this.safeString(data, "clientOrderId");
        if ((clientOrderId != null))
        {
            IDictionary<string, object> pending = this.safeDict(this.options, "pendingWsOrders", new Dictionary<string, object>() {});
            this.options["pendingWsOrders"] = this.omit(pending, clientOrderId);
            this.settleRequest(client, ("added-order:" + clientOrderId), ccxt.BaseExchange.FromOrder(order));
        }
    }

