    public virtual void handleCancelAllOrders(WebSocketClient client, Dictionary<string, object> message)
    {
        //
        //     {
        //         "event": "canceled-all-orders",
        //         "symbol": "BTC/USDC",
        //         "data": {
        //             "userId": "2bf436fc-43e6-459a-b647-6b446f72ad96",
        //             "cancelledOrders": [ "c5dfb28b-a306-4682-acdd-1271a299ca6b" ]
        //         }
        //     }
        //
        string? marketId = this.safeString(message, "symbol");
        Dictionary<string, object> market = this.safeMarket(marketId);
        IDictionary<string, object> data = this.safeDict(message, "data", new Dictionary<string, object>() {});
        List<object> ids = this.safeList(data, "cancelledOrders", new List<object>() {});
        List<object> orders = new List<object>() {};
        for (int i = 0; i < ids.Count; i++)
        {
            orders.Add(ccxt.BaseExchange.FromOrder(this.safeOrder(new Dictionary<string, object>() {
                { "info", message },
                { "id", this.safeString(ids, i) },
                { "symbol", this.safeString(market, "symbol") },
                { "status", "canceled" },
            }, market)));
        }
        this.settleRequest(client, ("canceled-all-orders:" + this.safeString(message, "symbol", "")), orders);
    }

    /**
     * @ignore
     * @method
     * @name bit2me#authenticate
     * @description authenticates the websocket connection with a short-lived token obtained over REST
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} the authentication message
     */
    public async virtual Task<object> authenticate(IDictionary<string, object> parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        string? url = ((string)(this.urlsApi != null && this.urlsApi.ContainsKey("ws") ? this.urlsApi["ws"] : null));
        var client = this.client(url);
        string messageHash = "authenticated";
        var future = client.reusableFuture(messageHash);
        object authenticated = this.safeValue(client.subscriptions, messageHash);
        if ((authenticated == null))
        {
            // the token is valid for one minute, it is only used to open the session
            Dictionary<string, object> response = await this.privatePostV1SigninApikey(parameters);
            //
            //     { "accessToken": { "token": "header.payload.signature", "expirationTime": 1794378427 } }
            //
            IDictionary<string, object> accessToken = this.safeDict(response, "accessToken", new Dictionary<string, object>() {});
            Dictionary<string, object> request = new Dictionary<string, object>() {
                { "event", "authenticate" },
                { "token", this.safeString(accessToken, "token") },
            };
            this.watch(url, messageHash, request, messageHash);
        }
        return await (future as Exchange.Future);
    }

    public virtual void handleAuthenticate(WebSocketClient client, object message)
    {
        //
        //     { "event": "authenticate" }
        //     { "event": "authenticate", "error": "jwt expired" }
        //
        string messageHash = "authenticated";
        string? error = this.safeString(message, "error");
        if ((error == null))
        {
            // the future is reusable, every later authenticate() call awaits the same resolved value
            Future future = client.getFuture(messageHash);
            (future as Future).resolve(message);
        } else
        {
            var exception = new AuthenticationError(((this.id + " ") + this.json(message)));
            client.reject(exception, messageHash);
            if ((client.subscriptions != null && client.subscriptions.ContainsKey(messageHash)))
            {
                ((IDictionary<string,object>)client.subscriptions).Remove(messageHash);
            }
        }
    }

    public virtual object handleSubscriptionStatus(WebSocketClient client, Dictionary<string, object> message)
    {
        //
        //     { "event": "subscribe", "symbol": "BTC/USDC", "subscription": { "name": "order-book" }, "result": "subscribed" }
        //     { "event": "unsubscribe" }
        //
        return message;
    }

    public virtual void handleErrorMessage(WebSocketClient client, object message)
    {
        //
        //     { "event": "added-order", "symbol": "BTC/USDC", "error": { "code": "PRICE_LOWER_MARKET_MIN", "minPrice": 0.001, "message": "The price can not be lower than 0.001" } }
        //     { "event": "canceled-order", "orderId": "73352609-a885-4dc6-99c4-8a03e5df6bda", "error": { "code": "ORDER_NOT_FOUND", "message": "The order with ID 73352609-a885-4dc6-99c4-8a03e5df6bda was not found" } }
        //
        string? eventVar = this.safeString(message, "event");
        IDictionary<string, object> error = this.safeDict(message, "error", new Dictionary<string, object>() {});
        string? code = this.safeString(error, "code");
        string? errorMessage = this.safeString(error, "message");
        string feedback = ((this.id + " ") + this.json(message));
        object exception = null;
        try
        {
            this.throwExactlyMatchedException(this.exceptionsExact, code, feedback);
            this.throwBroadlyMatchedException((this.exceptions != null && this.exceptions.ContainsKey("broad") ? this.exceptions["broad"] : null), errorMessage, feedback);
            exception = new ExchangeError(feedback);
        } catch(Exception e)
        {
            exception = e;
        }
        if (eventVar == "added-order")
        {
            // the error carries no client order id, reject every order of the symbol still waiting for a response
            string? marketId = this.safeString(message, "symbol");
            IDictionary<string, object> pending = this.safeDict(this.options, "pendingWsOrders", new Dictionary<string, object>() {});
            List<object> clientOrderIds = new List<object>(pending.Keys);
            for (int i = 0; i < clientOrderIds.Count; i++)
            {
                string? clientOrderId = ((string)clientOrderIds[i]);
                string? pendingMarketId = this.safeString(pending, clientOrderId);
                if ((pendingMarketId == marketId))
                {
                    this.settleRequest(client, ("added-order:" + clientOrderId), null, exception);
                    this.options["pendingWsOrders"] = this.omit((this.options != null && this.options.ContainsKey("pendingWsOrders") ? this.options["pendingWsOrders"] : null), clientOrderId);
                }
            }
        } else if (eventVar == "canceled-order")
        {
            this.settleRequest(client, ("canceled-order:" + this.safeString(message, "orderId", "")), null, exception);
        } else if (eventVar == "canceled-orders")
        {
            this.settleRequest(client, "canceled-orders", null, exception);
        } else if (eventVar == "canceled-all-orders")
        {
            this.settleRequest(client, ("canceled-all-orders:" + this.safeString(message, "symbol", "")), null, exception);
        } else if (eventVar == "subscribe")
        {
            // a refused subscription names the channel and the symbol it was asked for
            IDictionary<string, object> subscription = this.safeDict(message, "subscription", new Dictionary<string, object>() {});
            string? name = this.safeString(subscription, "name");
            string? marketId = this.safeString(message, "symbol");
            string? symbol = this.safeSymbol(marketId);
            Dictionary<string, object> hashes = new Dictionary<string, object>() {
                { "order-book", ("orderbook:" + symbol) },
                { "public-trades", ("trades:" + symbol) },
                { "my-orders", "orders" },
                { "my-trades", "myTrades" },
                { "my-balance", "balance" },
            };
            string? messageHash = this.safeString(hashes, name);
            if ((messageHash != null))
            {
                client.reject(exception, messageHash);
                if ((name == "my-orders") || (name == "my-trades"))
                {
                    // the private channels are account-wide, a symbol-scoped watchOrders / watchMyTrades waits on orders:SYMBOL / myTrades:SYMBOL
                    string scopedPrefix = (messageHash + ":");
                    List<object> pendingHashes = new List<object>(((IDictionary<string, ccxt.Exchange.Future>)client.futures).Keys);
                    for (int i = 0; i < pendingHashes.Count; i++)
                    {
                        string? pendingHash = ((string)pendingHashes[i]);
                        if (pendingHash.StartsWith(scopedPrefix))
                        {
                            client.reject(exception, pendingHash);
                        }
                    }
                }
                if (((name != null)) && (((name != null) && (client.subscriptions != null && client.subscriptions.ContainsKey(name)))))
                {
                    ((IDictionary<string,object>)client.subscriptions).Remove(name);
                }
                if (((messageHash != null) && (client.subscriptions != null && client.subscriptions.ContainsKey(messageHash))))
                {
                    ((IDictionary<string,object>)client.subscriptions).Remove(messageHash);
                }
            }
        }
    }

    public override void handleMessage(WebSocketClient client, object message)
    {
        string? eventVar = this.safeString(message, "event");
        if (eventVar == "authenticate")
        {
            this.handleAuthenticate(client, message);
            return;
        }
        IDictionary<string, object> error = ((IDictionary<string, object>)this.safeValue(message, "error"));
        if ((error != null))
        {
            this.handleErrorMessage(client, message);
            return;
        }
        Dictionary<string, object> methods = new Dictionary<string, object>() {
            { "order-book", this.handleOrderBook },
            { "public-trades", this.handleTrades },
            { "my-orders", this.handleOrder },
            { "my-trades", this.handleMyTrade },
            { "my-balance", this.handleBalance },
            { "added-order", this.handleCreateOrder },
            { "canceled-order", this.handleCancelOrder },
            { "canceled-orders", this.handleCancelOrders },
            { "canceled-all-orders", this.handleCancelAllOrders },
            { "subscribe", this.handleSubscriptionStatus },
            { "unsubscribe", this.handleSubscriptionStatus },
        };
        Delegate method = ((Delegate)this.safeValue(methods, eventVar));
        if ((method != null))
        {
            DynamicInvoker.InvokeMethod(method, new object[] { client, message});
        }
    }
